import{_ as s,h as o,i as e,c as r,v as t,p as n,x as l,m as E,e as d,S as A}from"./chunks/framework.Dvtg8yj2.js";const B=JSON.parse('{"title":"扩散蒸馏、CFG 与 VAE 潜空间","description":"","frontmatter":{"title":"扩散蒸馏、CFG 与 VAE 潜空间","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-diffusion-stack.md","filePath":"llm/atlas-diffusion-stack.md","lastUpdated":1788454257000}'),c={name:"llm/atlas-diffusion-stack.md"};function p(h,a,f,m,_,F){const i=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="扩散蒸馏、cfg-与-vae-潜空间" tabindex="-1">扩散蒸馏、CFG 与 VAE 潜空间 <a class="header-anchor" href="#扩散蒸馏、cfg-与-vae-潜空间" aria-label="Permalink to &quot;扩散蒸馏、CFG 与 VAE 潜空间&quot;">​</a></h1><div class="epigraph"><p>Atlas 作为潜空间扩散模型，可以使用扩散蒸馏、无分类器引导、偏移噪声日程以及 VAE 设计上的进展；这是栈的相容性，不是一张已公布的推理超参表。</p><footer>—— 改写自 World Labs Team, Atlas, 2026</footer></div><p>自回归解决「下一个元素是什么」，扩散解决「这一个高维连续元素怎么采样」。Atlas 是<a href="/llm/atlas-rectified-flow">rectified flow</a> 潜空间模型：先把图像或深度推进 VAE 潜变量，再在潜空间里学一条近直的流，推理时沿该流积分若干步。World Labs 把现代图像/视频模型的算法菜单点了一遍——蒸馏、classifier-free guidance（CFG）、shifted noise schedules、VAE 进展——作为它可以吸收的技术。本篇把这三块（蒸馏、CFG、VAE）写成世界模型栈里的杠杆，明确哪些是公开文献里的通用机制，哪些 Atlas 并未给出配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素空间扩散在 1440p 上不可行：通道宽、噪声日程难、U-Net 或 DiT 的 token 数按像素线性涨。VAE 把 \\(x\\) 压成 \\(z=E(x)\\)，生成发生在 \\(z\\) 上，解码 \\(D(z)\\) 再回到像素。潜空间解决的是维度，不自动解决步数：rectified flow 或 DDPM 仍可能要几十次网络前向才能得到一张干净潜变量。自回归再乘上帧数，一分钟镜头的 NFE（function evaluations）会爆。</p><p>第二件事是条件强度。空间上下文、相机 \\(P\\)、文本，都是条件 \\(c\\)。条件太弱，机位跟不住；太强，多样性崩掉，或者对错误条件过拟合。CFG 提供推理期旋钮：同一网络跑有条件与无条件，再外推。第三件事是步数与质量的交易，蒸馏把多步教师压成少步学生，服务才能接近可交互。三条问题分别打在表示、引导、预算上，合成一条推理栈。</p><h3 id="相容不是已经启用" tabindex="-1">相容不是已经启用 <a class="header-anchor" href="#相容不是已经启用" aria-label="Permalink to &quot;相容不是已经启用&quot;">​</a></h3><p>官方句子是 can make use of。合理解读：架构没有挡住这些算法；不合理解读：Atlas 推理一定用了某篇蒸馏论文的 \\(N=4\\)、一定 CFG scale 等于 7.5、一定 VAE 下采样 \\(8\\times\\)。参数量、潜宽、码本还是连续潜变量，均未披露。写栈是为了读对后续工程选择，不是为了伪造一张 Atlas 模型卡。</p><p><span class="marginnote">Rectified flow 把扩散看成学速度场 \\(v_\\theta(z_t,t)\\)，沿近直线积分。步数少时误差不同于 DDPM 的随机 Langevin。蒸馏与 CFG 的公式要写在 flow 的变量上，不要直接把 \\(\\epsilon\\)-预测的帖子抄过来当 Atlas 实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VAE 定义</p> \\[z = E(x),\\qquad \\hat{x}=D(z), \\]<p>训练通常含重建项与潜空间正则。生成器只看见 \\(z\\)。Rectified flow 在数据 \\(z_1\\) 与噪声 \\(z_0\\) 之间插值 \\(z_t=(1-t)z_0+t z_1\\)（约定可对调），回归速度</p> \\[v_\\theta(z_t,t,c)\\approx z_1-z_0. \\]<p>推理从噪声积分到数据。CFG 在 flow 里常用有条件与无条件速度的线性组合</p> \\[v_{\\mathrm{cfg}} = v_\\theta(z_t,t,\\varnothing) + s\\bigl(v_\\theta(z_t,t,c)-v_\\theta(z_t,t,\\varnothing)\\bigr), \\]<p>\\(s\\) 是引导尺度。\\(s=1\\) 回到条件生成；\\(s&gt;1\\) 强化 \\(c\\)，包括相机与空间上下文。无分类器训练要求以一定概率丢掉 \\(c\\)，才能学到 \\(v_\\theta(\\cdot,\\varnothing)\\)。Ho 与 Salimans 2022 年的 CFG 原写在 \\(\\epsilon\\) 预测上，思想同样适用。</p><p>蒸馏：教师用多步积分出干净 \\(\\hat{z}\\)，学生用更少步拟合同一位移，或拟合一致性条件（同一轨迹上不同 \\(t\\) 映到同一终点）。目标是把每帧 NFE 从几十降到个位数，而不把空间一致性整段丢掉。Shifted noise schedules 改变 \\(t\\) 的采样密度，让高噪声或低噪声段多训练，属于同一栈上的日程旋钮。</p>',18)),(e(),n(A,null,{default:l(()=>[d(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22RGB%20%2F%20%E6%B7%B1%E5%BA%A6%22%5D%20--%3E%20E%5B%22VAE%20%E7%BC%96%E7%A0%81%E5%99%A8%20E%22%5D%0A%20%20E%20--%3E%20Z%5B%22%E6%BD%9C%E5%8F%98%E9%87%8F%20z%22%5D%0A%20%20Z%20--%3E%20FLOW%5B%22%E6%9D%A1%E4%BB%B6%20rectified%20flow%22%5D%0A%20%20C%5B%22%E7%A9%BA%E9%97%B4%E4%B8%8A%E4%B8%8B%E6%96%87%20%2F%20%E7%9B%B8%E6%9C%BA%20%2F%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20FLOW%0A%20%20FLOW%20--%3E%20CFG%5B%22CFG%20%E6%B7%B7%E5%90%88%E6%9C%89%E6%97%A0%E6%9D%A1%E4%BB%B6%E9%80%9F%E5%BA%A6%22%5D%0A%20%20CFG%20--%3E%20DIST%5B%22%E5%8F%AF%E9%80%89%E8%92%B8%E9%A6%8F%E5%B0%91%E6%AD%A5%E7%A7%AF%E5%88%86%22%5D%0A%20%20DIST%20--%3E%20D%5B%22VAE%20%E8%A7%A3%E7%A0%81%E5%99%A8%20D%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E5%83%8F%E7%B4%A0%E6%88%96%E6%B7%B1%E5%BA%A6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="条件-里有几何" tabindex="-1">条件 \\(c\\) 里有几何 <a class="header-anchor" href="#条件-里有几何" aria-label="Permalink to &quot;条件 $c$ 里有几何&quot;">​</a></h3><p>文本扩散的 \\(c\\) 往往是句子嵌入。Atlas 的 \\(c\\) 含位姿与已锚定视图，CFG 外推的是「更跟机位、更跟参考图」，副作用可能是过饱和、纹理重复、把想象区域变得过于「像训练集里的房间」。几何条件比文本更硬，高 \\(s\\) 不一定单调更好。方法上应对相机跟随与纹理自然度做二维扫描，而不是沿用图像生成博客里的默认 scale。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>潜空间让 Transformer 看到的序列长度按压缩比下降。若空间下采样 \\(f\\)，一张 \\(H\\times W\\) 图变成约 \\((H/f)\\times(W/f)\\) 个潜 token。1440p 能否直接进 VAE，还是先在较低分辨率生成再上采样，官方未说。机制上，VAE 重建误差会变成几何误差：深度图若走同一 \\(D\\)，低频对了、高频锯齿会在点云里变成层状噪声。世界模型比纯观赏图像更不能容忍「看起来差不多」的潜空间损失。</p><p>CFG 的几何含义是在速度场里沿条件梯度走得更远。对离散文本条件，这常提高提示词服从；对连续位姿，\\(s\\) 过大会让轨迹过冲，近平面物体放大失真。无条件支路必须在训练里见过「没有这张参考图」或「没有这段文本」，否则 \\(\\varnothing\\) 的定义不清——丢掉文本但保留位姿，与全部丢掉，是两种 CFG。公开材料没有写清丢掉策略。</p><p><span class="marginnote">蒸馏缩短积分路径，会抹掉教师在多步里修正的高频。对跟机位这种低频几何，少步往往够；对文字渲染、细杆、远景窗户，少步会先坏。服务上这与 KV 缓存正交：蒸馏减的是每元素内部的网络次数，缓存减的是元素之间的注意力重复。</span></p><h3 id="三块杠杆如何叠在自回归上" tabindex="-1">三块杠杆如何叠在自回归上 <a class="header-anchor" href="#三块杠杆如何叠在自回归上" aria-label="Permalink to &quot;三块杠杆如何叠在自回归上&quot;">​</a></h3><p>每个自回归元素调用一次（或 \\(N\\) 次）潜空间生成。VAE 决定元素有多宽；CFG 决定这次生成多听话；蒸馏决定 \\(N\\)。长视频的总 NFE 约为 \\(T\\times N\\)。把 \\(N\\) 从 50 蒸到 4，比把 Transformer 再快 20% 更划算，前提是空间锚不漂。若蒸馏学生在第 100 帧开始忘了第一张参考图，省下的步数会买来<a href="/llm/atlas-camera-controlled-video">长镜头</a> 的崩坏。因此蒸馏必须在长序列上验收，而不能只在单张 FID 上验收。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有 Atlas 的 VAE 论文、没有潜维、没有是否对深度共用编码器。深度与 RGB 共用 \\(E\\) 会共享纹理先验，分用则对齐成本高。任选都合理，都不能从博客反推。CFG 在多条件（文本 + 多图 + 轨迹）下如何合成一个 \\(c\\)、如何分别引导，同样未写；有人会对不同条件用不同 \\(s\\)，那是通用做法，不是 Atlas 规格。</p><p>蒸馏文献很多（渐进蒸馏、一致性模型、 adversarial 微调），指定哪一篇会变成伪造。只保留机制：少步学生近似多步流。Shifted schedules、潜空间正则系数，全部属于未披露超参。评测若用公司相机跟随人类偏好，应记住对照模型可能没有同等 CFG 与同等原生位姿，栈的优势和模型的优势会缠在一起。</p><p><span class="marginnote">图像生成不是 Atlas 的主任务，但同一 VAE 与 CFG 也会作用在文生图和 360 全景上。主任务验收仍应是空间一致性与跟机，而不是单看提示词美学。把通用扩散博客的最佳实践整包套到世界模型上，容易把几何条件当成又一句 prompt。</span></p><p>早鸟阶段外部无法做步数–质量曲线。工程规划可以把 \\(N\\)、CFG \\(s\\)、VAE 重建 PSNR 列为必测旋钮，等待权重或 API 暴露它们。在那之前，栈的正确态度是：生成发生在潜空间流模型上，LLM 式 KV 管序列轴，扩散算法管元素轴。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Atlas 在 VAE 潜空间上做 rectified flow；VAE 压缩空间分辨率，流模型负责连续采样。</li><li>CFG 用有无条件速度外推，把相机与空间上下文的服从当成可调尺度 \\(s\\)。</li><li>蒸馏降低每帧 NFE，必须在长自回归上测一致性，不能只看单帧。</li><li>官方列出这些算法是架构相容，不是已公布的推理配方；不要编造步数与潜宽。</li><li>深度作为连续场，VAE 重建误差会变成点云噪声。</li><li>元素轴的扩散栈与序列轴的 KV 缓存是正交的两笔账。</li><li>出处：World Labs Team，<em>Atlas: A World Model for Spatial Intelligence</em>，World Labs Blog，2026；CFG 见 Ho 与 Salimans，<em>Classifier-Free Diffusion Guidance</em>，2022；VAE 见 Kingma 与 Welling，<em>Auto-Encoding Variational Bayes</em>，2014。Rectified flow 见 Liu 等，<em>Flow Straight and Fast</em>，ICLR 2023。</li></ul>',15))])}const C=s(c,[["render",p]]);export{B as __pageData,C as default};
